const GROUPS=[...new Set(STEPS.map(s=>s.grp))];
const NEED_NAMES={nome:'il tuo nome',cognome:'il tuo cognome',A:'la superficie della casa',regione:'la regione',prov:'la provincia',Tp:'la temperatura di progetto',tilt:'l’inclinazione del tetto',Lone:'la distanza tra pannelli e locale caldaia'};
const NEED_STEP={nome:'copertina',cognome:'copertina',A:'casa',regione:'casa',prov:'casa',Tp:'casa',tilt:'tetto',Lone:'tubi'};
// ===================== VERIFICHE LAMPO: prima di ogni fase lo studente dice cosa sta per fare =====================
const LAMPO={
 casa:[['Perché ti serve sapere in che zona d’Italia è la casa?',['Per sapere quanto sole c’è e quindi quanti pannelli servono','Per scegliere il colore dei pannelli','Per sapere quanti piani ha la casa'],'La zona (Nord, Centro, Sud) cambia il coefficiente della tabella: più sole, meno pannelli.'],
  ['A cosa serve la temperatura esterna di progetto?',['A decidere quanto antigelo mettere','A calcolare il numero di pannelli','A scegliere il diametro del tubo'],'Serve per l’antigelo: il circuito non deve gelare nelle notti più fredde.']],
 tetto:[['Qual è l’orientamento migliore per i pannelli in Italia?',['Verso Sud','Verso Nord','Non conta'],'Nel nostro emisfero il sole a mezzogiorno sta a Sud.']],
 pannello:[['Quale di questi numeri NON prendi dalla scheda tecnica del pannello?',['La superficie della casa','La superficie del pannello','I litri di liquido contenuti'],'La superficie della casa è un dato del progetto, non dalla scheda del pannello.']],
 numero:[['Cosa stai per calcolare in questa fase?',['Quanti pannelli servono alla casa','Quanti litri d’acqua servono','Il diametro dei tubi'],'Prima la superficie di pannelli che serve, poi il numero di pannelli.'],
  ['Quale tabella ti serve?',['Quella dei coefficienti per impianti combinati','La Tab. 7A dei tubi','La tabella del glicole'],'Il coefficiente dice quanti m² di pannello servono ogni 10 m² di casa.']],
 posa:[['Cosa controlli in questa fase?',['Che i pannelli ci stiano sul tetto','Quanta acqua serve','Quanto deve essere grande il vaso'],'Le misure dei pannelli devono stare nella falda, lontano dai bordi e dal camino.']],
 portata:[['La portata è…',['quanti litri all’ora passano nei pannelli','quanti litri contiene il serbatoio','la pressione della pompa'],'Si misura in l/h: è l’acqua che la pompa deve far girare.'],
  ['Da quale dato parti?',['La superficie di un pannello','La temperatura esterna','La lunghezza del tubo'],'La regola è 40 l/h per ogni m² di pannello.']],
 tubi:[['Per scegliere il tubo nella Tab. 7A quale numero cerchi?',['La portata G','Il numero di pannelli','La temperatura di progetto'],'Nelle celle della Tab. 7A ci sono le portate: cerchi la tua G.'],
  ['Su quale riga della Tab. 7A parti?',['r = 12 mm c.a. per metro','La prima riga in alto','La riga del tuo diametro'],'Si impone una perdita tra 10 e 15 mm per metro: noi usiamo 12.']],
 isola:[['Quali due dati ti servono per lo spessore dell’isolante?',['λ dell’isolante e diametro esterno del tubo','Portata e numero di pannelli','Temperatura e glicole'],'Nella Tabella 2 (Legge 10) le righe sono λ, le colonne i diametri.']],
 gelo:[['Cosa decidi in questa fase?',['Quanto glicole mettere nel circuito','Quanti pannelli montare','Quanto è grande il serbatoio'],'Il glicole abbassa la temperatura a cui il liquido gela.']],
 pompa:[['La prevalenza della pompa è…',['la somma di tutte le perdite di carico del circuito','la portata dei pannelli','la potenza dello scambiatore'],'La pompa deve vincere tubi, curve, pannelli e scambiatore.'],
  ['Quale perdita calcoli per prima?',['Quella continua nei tubi: r × lunghezza','Quella dello scambiatore','Quella del serbatoio'],'Si parte dai tubi, poi curve e raccordi, poi pannelli.']],
 scamb:[['Lo scambiatore si dimensiona in base a…',['la superficie dei pannelli installati','la lunghezza del tubo','il volume del vaso'],'Ogni m² di pannello porta circa 400 kcal/h.']],
 vaso:[['A cosa serve il vaso di espansione?',['Ad accogliere il liquido che si dilata col caldo','A tenere l’acqua calda per la sera','A filtrare l’acqua'],'Senza vaso, la pressione salirebbe e aprirebbe la valvola.'],
  ['Quale volume calcoli prima di tutto?',['I litri contenuti nel circuito','I litri del serbatoio','La portata della pompa'],'Si parte dal contenuto: pannelli, tubi e scambiatore.']],
 serb:[['Il serbatoio si dimensiona con…',['litri per m² di pannello','litri per pannello','litri per persona'],'La regola pratica è 50 ÷ 60 litri per m² di pannello.']],
 schemi:[['Chi decide quando accendere la pompa solare?',['La centralina differenziale','Il termostato di casa','La valvola di sicurezza'],'Confronta la sonda del pannello con quella del serbatoio.']]};
for(const st of STEPS){const L=LAMPO[st.id];if(!L)continue;const pre=L.map(([q,o,why],i)=>({id:`L_${st.id}_${i}`,kind:'pick',lampo:true,key:`_L${st.id}${i}`,q:()=>`⚡ Verifica lampo: ${q}`,opts:()=>o.map((t,j)=>['abc'[j],t]),correct:()=>'a',bad:()=>'Non è questa. '+why,ok:()=>why}));st.tasks=[...pre,...(st.tasks||[])]}
